funkin_backend_utils_CoolUtil.parseNumberRange = function(input) {
	var result = [];
	var parts = input.split(",");
	var _g = 0;
	while(_g < parts.length) {
		var part = parts[_g];
		++_g;
		part = StringTools.trim(part);
		var idx = part.indexOf("..");
		if(idx != -1) {
			var start = Std.parseInt(StringTools.trim(part.substring(0,idx)));
			var end = Std.parseInt(StringTools.trim(part.substring(idx + 2)));
			if(start == null || end == null) {
				continue;
			}
			if(start < end) {
				var _g1 = start;
				var _g2 = end + 1;
				while(_g1 < _g2) {
					var j = _g1++;
					result.push(j);
				}
			} else {
				var _g3 = end;
				var _g4 = start + 1;
				while(_g3 < _g4) {
					var j1 = _g3++;
					result.push(start + end - j1);
				}
			}
		} else {
			var num = Std.parseInt(part);
			if(num != null) {
				result.push(num);
			}
		}
	}
	return result;
};
funkin_backend_utils_CoolUtil.formatNumberRange = function(numbers,seperator) {
	if(seperator == null) {
		seperator = ",";
	}
	if(numbers.length == 0) {
		return "";
	}
	var result = [];
	var i = 0;
	while(i < numbers.length) {
		var start = numbers[i];
		var end = start;
		var direction = 0;
		if(i + 1 < numbers.length) {
			if(numbers[i + 1] == end + 1) {
				direction = 1;
			} else if(numbers[i + 1] == end - 1) {
				direction = -1;
			}
		}
		if(direction != 0) {
			while(i + 1 < numbers.length && numbers[i + 1] == end + direction) {
				end = numbers[i + 1];
				++i;
			}
		}
		if(start == end) {
			result.push("" + start);
		} else if(start + direction == end) {
			result.push("" + start + "," + end);
		} else {
			result.push("" + start + ".." + end);
		}
		++i;
	}
	return result.join(seperator);
};
