	,openPanel: function(newPage) {
		if(newPage < 3 && this.selected == "") {
			return;
		}
		if(this.panelOpen && this.page != newPage) {
			this.panelOpacity = Math.min(this.panelOpacity,0.65);
		}
		this.commitFocus();
		this.page = newPage;
		this.panelOpen = true;
		this.refreshPanel = true;
	}
	,closePanel: function() {
		this.commitFocus();
		this.panelOpen = false;
		this.refreshPanel = true;
	}
