funkin_options_Options.load = function() {
	if(funkin_options_Options.__save == null) {
		funkin_options_Options.__save = new funkin_savedata_WebDemoSave();
	}
	funkin_options_Options.__save.bind("options","CodenameEngine");
	funkin_options_Options.__load();
	if(!funkin_backend_MenuTheme.isValid(funkin_options_Options.menuTheme)) {
		funkin_options_Options.menuTheme = "classic";
	}
	if(!funkin_options_Options.__eventAdded) {
		openfl_Lib.get_application().onExit.add(function(i) {
			haxe_Log.trace("Saving settings...",{ fileName : "source/funkin/options/Options.hx", lineNumber : 156, className : "funkin.options.Options", methodName : "load"});
			funkin_options_Options.save();
		});
		funkin_options_Options.__eventAdded = true;
	}
	flixel_FlxG.sound.set_volume(funkin_options_Options.volume);
	funkin_options_Options.applySettings();
};
funkin_options_Options.applySettings = function() {
	funkin_options_Options.naughtyness = false;
	funkin_options_Options.menuTheme = "classic";
	funkin_options_Options.showStartupVideo = funkin_options_Options.showWarningVideo = false;
	funkin_options_Options.antialiasing = false;
	funkin_options_Options.applyKeybinds();
	flixel_FlxG.game.stage.set_quality((flixel_FlxG.enableAntialiasing = funkin_options_Options.antialiasing) ? 2 : 0);
	flixel_FlxG.autoPause = funkin_options_Options.autoPause;
	flixel_FlxG.set_drawFramerate(flixel_FlxG.set_updateFramerate(funkin_options_Options.framerate));
};
funkin_options_Options.applyKeybinds = function() {
	funkin_options_PlayerSettings.solo.setKeyboardScheme(funkin_backend_system_KeyboardScheme.Solo);
	funkin_options_PlayerSettings.player1.setKeyboardScheme(funkin_backend_system_KeyboardScheme.Duo(true));
	funkin_options_PlayerSettings.player2.setKeyboardScheme(funkin_backend_system_KeyboardScheme.Duo(false));
};
