var funkin_options_categories_AppearanceOptions = function() {
	var _gthis = this;
	funkin_options_OptionsScreen.call(this,"Appearance","Change Appearance options such as Flashing menus...");
	this.add(new funkin_options_type_TextOption("HUD Editor","Arrange the HUD, notes and strumlines, add widgets and save presets.",function() {
		funkin_options_Options.save();
		var nextState = new funkin_editors_hud_HudEditorState();
		if(flixel_FlxG.game._state.switchTo(nextState)) {
			flixel_FlxG.game._requestedState = nextState;
		}
	}));
	this.add(new funkin_options_type_TextOption("Themes","Choose the look and music of the menus. Gameplay keeps its own colours.",function() {
		_gthis.parent.add(new funkin_options_categories_ThemesOptions());
	}));
	this.add(new funkin_options_type_NumOption("Framerate","Maximum frames per second. Higher values make motion smoother but require more performance.",30,240,10,"framerate",$bind(this,this.__changeFPS)));
	this.add(new funkin_options_type_Checkbox("Antialiasing","If unchecked, will disable antialiasing on every sprite. Can boost performances at the cost of sharper, more pixely sprites.","antialiasing"));
	this.add(new funkin_options_type_Checkbox("Colored Healthbar","If unchecked, the game will use the orginal red/green health bar from the week 6 fnf game.","colorHealthBar"));
	this.add(new funkin_options_type_Checkbox("Pixel Perfect Effect","If checked, Week 6 will have a pixel perfect effect to it enabled, aligning every pixel on the screen.","week6PixelPerfect"));
	this.add(new funkin_options_type_Checkbox("Gameplay Shaders","If unchecked, gameplay shaders (visual effects like Thorns's Chromatic Aberration) wont be loaded; this may be helpful on weak devices.","gameplayShaders"));
	this.add(new funkin_options_type_Checkbox("Flashing Menu","If unchecked, will disable menu flashing when you select an option in the Main Menu, and other flashes will be slower.","flashingMenu"));
	this.add(new funkin_options_type_Checkbox("Low Memory Mode","If checked, will disable certain background elements in stages to reduce memory usage.","lowMemoryMode"));
	this.add(new funkin_options_type_Checkbox("Auto Pause","If checked, switching windows will pause the game.","autoPause"));
};
