	this.add(this.offsetSetting = new funkin_options_type_NumOption("Song Offset","Adjust song timing in milliseconds. Listen to the clicks and compare them with the music beat.",-999,999,1,"songOffset",$bind(this,this.__changeOffset)));
	this.add(new funkin_options_type_Checkbox("Naughtyness","If unchecked, censorship is applied to the ENTIRE game. It is recommended to uncheck this option if you are under 16 years of age.","naughtyness"));
	this.add(new funkin_options_type_Checkbox("Camera Zoom on Beat","If unchecked, will stop the camera from zooming in every 4 beats","camZoomOnBeat"));
