				var jy = arb.ny * arb.c1.jnAcc + arb.nx * arb.c1.jtAcc;
				var t = arb.b1.imass;
				arb.b1.velx -= jx * t;
				arb.b1.vely -= jy * t;
				arb.b1.angvel -= arb.b1.iinertia * (jy * arb.c1.r1x - jx * arb.c1.r1y);
				var t1 = arb.b2.imass;
				arb.b2.velx += jx * t1;
				arb.b2.vely += jy * t1;
				arb.b2.angvel += arb.b2.iinertia * (jy * arb.c1.r2x - jx * arb.c1.r2y);
