					var jx1 = arb.nx * arb.c2.jnAcc - arb.ny * arb.c2.jtAcc;
					var jy1 = arb.ny * arb.c2.jnAcc + arb.nx * arb.c2.jtAcc;
					var t2 = arb.b1.imass;
					arb.b1.velx -= jx1 * t2;
					arb.b1.vely -= jy1 * t2;
					arb.b1.angvel -= arb.b1.iinertia * (jy1 * arb.c2.r1x - jx1 * arb.c2.r1y);
